func main() {
    // Запуск горутины
    go doWork("task1")
    go doWork("task2")

    // Канал для результата
    ch := make(chan int)
    go func() {
        result := compute()
        ch <- result  // отправка
    }()
    val := <-ch  // приём, блокируется до отправки

    // WaitGroup для ожидания
    var wg sync.WaitGroup
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(i int) {
            defer wg.Done()
            doWork(fmt.Sprintf("task%d", i))
        }(i)
    }
    wg.Wait()  // ждём все

    // Контекст для отмены
    ctx, cancel := context.WithCancel(context.Background())
    go func() {
        for {
            select {
            case <-ctx.Done():
                return  // завершение по отмене
            default:
                doStep()
            }
        }
    }()
    cancel()  // сигнал остановки
}
