// O(n) — линейный поиск
func linearSearch(arr []int, target int) int {
    for i, v := range arr {  // один проход
        if v == target {
            return i
        }
    }
    return -1
}
// Время: O(n), память: O(1)

// O(log n) — бинарный поиск
func binarySearch(arr []int, target int) int {
    lo, hi := 0, len(arr)-1
    for lo <= hi {
        mid := (lo + hi) / 2
        if arr[mid] == target {
            return mid
        } else if arr[mid] < target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    return -1
}
// Время: O(log n), память: O(1)

// O(n²) — bubble sort
func bubbleSort(arr []int) {
    for i := 0; i < len(arr); i++ {
        for j := 0; j < len(arr)-1; j++ {  // вложенный цикл
            if arr[j] > arr[j+1] {
                arr[j], arr[j+1] = arr[j+1], arr[j]
            }
        }
    }
}
// Время: O(n²), память: O(1)

// O(2^n) — naive Fibonacci
func fib(n int) int {
    if n <= 1 { return n }
    return fib(n-1) + fib(n-2)  // дерево вызовов
}
// Время: O(2^n), память: O(n) (стек)
// С memoization: O(n) время, O(n) память
